/**
 * Request a password-reset email.
 * Backend endpoint: POST /account-recovery/
 * Payload: { email }
 */
export async function requestAccountRecovery(email) {
  const { data } = await api.post('/account-recovery/', { email });
  return data;
}

/**
 * Confirm a password reset with the token from the email.
 * Backend endpoint: POST /password-reset/confirm/
 * Payload: { uid, token, password }
 */
export async function confirmPasswordReset(uid, token, password) {
  const { data } = await api.post('/password-reset/confirm/', {
    uid,
    token,
    password,
  });
  return data;
}

